const inp = $('Agent Input').first().json;
const lead = inp.lead;
const ctx = inp.context || { known: {}, ask_next: [], catalog: '' };
const clean = s => String(s || '').replace(/[{}]/g, ' ');
const hist = $input.all().map(i => i.json).filter(r => r.role);
const fmt = v => (v && typeof v === 'object') ? [v.min, v.max, v.raw].filter(x => x).join(' / ') : v;
const known = Object.entries(ctx.known || {}).map(e => '- ' + e[0] + ': ' + clean(fmt(e[1]))).join('\n') || '- nothing yet';
const history = hist.slice(-12).map(r => (r.role === 'user' ? 'Customer: ' : 'Assistant: ') + clean(r.text)).join('\n') || 'first message';
// Uncertain answers from earlier turns are clarified FIRST, before asking anything new
const CORE = ['asset', 'budget', 'financing', 'timeline'];
const unclear = (lead.uncertain_fields || []).filter(f => CORE.includes(f));
const ask = [...unclear, ...(ctx.ask_next || []).filter(s => !unclear.includes(s))].slice(0, 2);
const askNext = ask.join(', ') || 'nothing missing - thank the customer and say a sales advisor will follow up';
const system = [
  'You are FANA assistant (مساعد فنا), the Arabic sales-qualification assistant of FANA for the Al Tilal Al Sharqiya auction (مزاد التلال الشرقية): an electronic real-estate auction (Infath, on the Soum platform) of 11 assets in Dammam and Al Khobar.',
  'CATALOG - the only properties that exist (id: description):',
  clean(ctx.catalog),
  'STYLE: natural, warm Saudi/Gulf Arabic. Keep it short: a brief acknowledgement, then at most TWO questions, only about the items in ASK_NEXT (in that order). Never ask again about KNOWN FACTS. Use the customer name if known.',
  'HARD RULES:',
  '1. Never state or estimate prices, opening prices, deposits, areas, or any property detail that is not written in CATALOG. If asked about price, say prices are decided by bidding in the auction and a sales advisor will share the details and entry terms, then continue qualifying.',
  '2. If the customer asks for a human, a person or an employee, confirm warmly that a sales advisor will contact them soon, and ask nothing else.',
  '3. If the customer asks to be contacted later, acknowledge it and ask what time suits them.',
  '4. If the customer says stop or do not contact me, apologise briefly and stop. If the customer is simply not interested, thank them politely and ask nothing else.',
  '5. CLARIFY FIRST: if the LATEST CUSTOMER MESSAGE answers something vaguely (for example على حسب، يمكن، الله يسهل، ما أدري about budget, financing or timeline), your reply MUST first ask one short, friendly clarifying question about THAT item (e.g. offer rough ranges), before any other question. Never guess the value.',
  'OUTPUT: respond with ONE JSON object only, no markdown. Keys:',
  '- reply_ar: your Arabic message to the customer.',
  '- extracted: an object. Include ONLY fields the customer stated in the LATEST CUSTOMER MESSAGE. Possible keys: interested_asset, budget, financing, timeline, buyer_type, investment_purpose, auction_experience, preferred_contact. Each is an object with keys value, confidence (0 to 1) and evidence (an exact short quote copied character-for-character from the latest message). budget instead uses keys raw (the exact budget words of the customer), confidence and evidence.',
  '  Allowed values: interested_asset = a catalog id, or when no specific asset one of villa, apartment, residential_building, commercial_building, commercial_land. financing = cash, financing_approved, financing_in_progress, financing_needed. timeline = this_auction, within_3_months, later. buyer_type = individual, company. investment_purpose = residence, investment, business. auction_experience = yes, no. preferred_contact = call, whatsapp, email.',
  '- intent: an object with keys value (high = wants to bid and is ready; medium = interested but exploring; low = only asks prices or is just browsing; unknown) and confidence.',
  '- flags: an object with boolean keys, each true ONLY when the customer clearly says it: human_requested (asks to talk to a person/employee now); price_only (only asks about prices); contact_later (asks to be contacted at a later time); opt_out (explicitly asks to STOP messages or NOT be contacted at all, e.g. لا تتصلوا، لا تراسلوني - saying they are not interested is NOT opt_out); not_interested (says they are not interested / do not want to buy).',
  'If you are unsure of a value, give a low confidence instead of inventing it. Never invent customer data.'
].join('\n');
const user = 'KNOWN FACTS (do not ask again):\n' + known +
  (unclear.length ? '\n\nUNCLEAR EARLIER ANSWERS (clarify these first): ' + unclear.join(', ') : '') +
  '\n\nASK_NEXT: ' + askNext + '\n\nCONVERSATION SO FAR:\n' + history + '\n\nLATEST CUSTOMER MESSAGE:\n' + clean(lead.message_text);
const allCustomer = hist.filter(r => r.role === 'user').map(r => r.text).concat([lead.message_text]).join('\n');
return [{ json: { system_prompt: system, user_prompt: user, all_customer_text: allCustomer, ask_next_effective: ask } }];

const r = $input.first().json;
const lead = r.lead;
const now = new Date().toISOString();
return [
  { json: { lead_key: lead.lead_key, role: 'user', text: lead.message_text, at: now, meta: JSON.stringify({ event_key: lead.last_event_key || lead.event_key }) } },
  { json: { lead_key: lead.lead_key, role: 'assistant', text: r.reply_ar, at: now, meta: JSON.stringify({ reply_source: r.reply_source, accepted: r.report.accepted, rejected: r.report.rejected, changed: r.report.changed, guard: r.guard.violations, llm_error: $('Prepare Apply AI').first().json.llm_error }) } }
];

const r = $('Core: Apply AI & Score').first().json;
const inp = $('Agent Input').first().json;
return [{ json: { ok: r.ok, lead: r.lead, is_new: inp.is_new, context: r.context, reply_ar: r.reply_ar, reply_source: r.reply_source, report: r.report, guard: r.guard, llm_error: $('Prepare Apply AI').first().json.llm_error } }];
